\label{thm0.7}
Assume that $\phi, \phi'$ are nondegenerate stability conditions of degrees $d,d'$ respectively, and that $n \geq 1$. We have the following.
\begin{enumerate}
\item[(i)] The associated graded ${\mathbb{H}}^{d, \phi}_{g,n}$ is a bigraded algebra over $H^*(\overline{{\mathcal M}}_{g,n}, {\mathbb{Q}})$ with elements in $H^m(\overline{{\mathcal M}}_{g,n}, {\mathbb{Q}})$ of bigrading $(0,m)$.

\item[(ii)] There is an isomorphism 
\[
{\mathbb{H}}^{d,\phi}_{g,n} \simeq {\mathbb{H}}^{d',\phi'}_{g,n}
\]
of bigraded $H^*(\overline{{\mathcal M}}_{g,n}, {\mathbb{Q}})$-algebras.
\end{enumerate}

When $n=0$, nondegenerate stability conditions of degree $d$ exist if and only if 
\begin{equation}\label{existence}
\mathrm{gcd}(d + 1 - g, 2g - 2) = 1;
\end{equation}
see \cite[Remark 5.12]{KP}. Thus, the best we can expect is that both statements of Theorem \ref{thm0.7} hold for those values of $d$ satisfying the numerical condition \eqref{existence}. Our proof does not cover this case due to the absence of a nondegenerate stability condition of degree $0$.

\label{thm0.8}
Assume that $\phi, \phi'$ are nondegenerate stability conditions for the reduced locally planar curve $C_0$. We have the following.
\begin{enumerate}
\item[(i)] The associated graded ${\mathbb{H}}^{\phi}_{C_0}$ is a bigraded ${\mathbb{Q}}$-algebra.

\item[(ii)] There is an isomorphism 
\[
{\mathbb{H}}^{\phi}_{C_0} \simeq {\mathbb{H}}^{\phi'}_{C_0}
\]
of bigraded ${\mathbb{Q}}$-algebras.
\end{enumerate}

\label{prop:halfFV}
For all $i + j < 2g$, we have
\begin{gather*}
\tag{FV1} ({\mathfrak{F}}^d)^{-1}_j\circ {\mathfrak{F}}^d_i = 0 \in \mathrm{CH}_{3g - i - j + \dim B}(\overline{J}_C^\vee \times_B \overline{J}_C^\vee), \\
\tag{FV2} {\mathfrak{F}}^d_j \circ ({\mathfrak{F}}^d)^{-1}_i = 0 \in \mathrm{CH}_{3g - i - j + \dim B}(\overline{J}_C^d \times_B \overline{J}_C^d).
\end{gather*}

\label{thm:realize}
For $0 \leq k \leq 2g$, the natural inclusion $\mathrm{Im}({\mathfrak{p}}^d_{\leq k}) \to \pi_{d*}{\mathbb{Q}}_{\overline{J}_C^d}$ realizes the perverse truncation
\[
{^{\mathfrak{p}}}\tau_{\leq k + \dim B}(\pi_{d*}{\mathbb{Q}}_{\overline{J}_C^d}) \to \pi_{d*}{\mathbb{Q}}_{\overline{J}_C^d}
\]
and provides a non-canonical splitting
\begin{equation} \label{eq:split1}
\pi_{d*}{\mathbb{Q}}_{\overline{J}_C^d} \simeq {^{\mathfrak{p}}}\tau_{\leq k + \dim B}(\pi_{d*}{\mathbb{Q}}_{\overline{J}_C^d}) \oplus {^{\mathfrak{p}}}\tau_{\geq k + 1+\dim B}(\pi_{d*}{\mathbb{Q}}_{\overline{J}_C^d}).
\end{equation}
Similarly, the inclusion $\mathrm{Im}({\mathfrak{p}}^\vee_{\leq k}) \to \pi^\vee_*{\mathbb{Q}}_{\overline{J}_C^\vee}$ realizes the perverse truncation
\[
{^{\mathfrak{p}}}\tau_{\leq k + \dim B}(\pi^\vee_*{\mathbb{Q}}_{\overline{J}_C^\vee}) \to \pi^\vee_*{\mathbb{Q}}_{\overline{J}_C^\vee}
\]
and provides a non-canonical splitting
\begin{equation} \label{eq:split2}
\pi^\vee_*{\mathbb{Q}}_{\overline{J}_C^\vee} \simeq {^{\mathfrak{p}}}\tau_{\leq k + \dim B}(\pi^\vee_*{\mathbb{Q}}_{\overline{J}_C^\vee}) \oplus {^{\mathfrak{p}}}\tau_{\geq k + 1+\dim B}(\pi^\vee_*{\mathbb{Q}}_{\overline{J}_C^\vee}).
\end{equation}

\label{cor:mainint}
For integers $d, d'$, there is an isomorphism
\[
{\mathbb{H}}^d \simeq {\mathbb{H}}^{d'}
\]
of bigraded $H^*(B, {\mathbb{Q}})$-algebras.

\label{def:DAB}
A dualizable abelian fibration consists of the following data
\[
(M, B, M^\vee, {\mathcal P}, {\mathcal K}).
\]
Here $\pi: M \to B$ is an abelian fibration of relative dimension $g$ with a dual abelian fibration $\pi^\vee: M^\vee \to B$ satisfying the following.

\begin{enumerate}
    \item[(a1)] (Poincar\'e) There is a normalized Poincar\'e complex~${{\mathcal P}} \in D^b\mathrm{Coh}(M^\vee \times_B M)$ which admits an inverse ${{\mathcal P}}^{-1} \in D^b\mathrm{Coh}(M \times_B M^\vee)$, \emph{i.e.},
    \begin{equation*} \label{eq:dual}
    {{\mathcal P}}^{-1} \circ {{\mathcal P}} \simeq {\mathcal O}_{\Delta_{M^\vee/B}}, \quad   {{\mathcal P}}\circ {\mathcal P}^{-1} \simeq {\mathcal O}_{\Delta_{M/B}}.
    \end{equation*}
    \item[(a2)] (Convolution) There is an object ${\mathcal K} \in D^b\mathrm{Coh}(M^\vee \times_B M^\vee \times_B M^\vee)$ supported in codimension $\geq g$, which satisfies
    \begin{equation}\label{convolution}
    {\mathcal P} \circ {\mathcal K} \simeq {\mathcal O}_{\Delta^\mathrm{sm}_{M/B}}\circ ({{\mathcal P}} \boxtimes {{\mathcal P}} ).
    \end{equation}
    Here $\Delta^\mathrm{sm}_{M/B} \subset M\times_B M \times_B M$ is the small relative diagonal, and ${\mathcal O}_{\Delta^\mathrm{sm}_{M/B}}\circ ({{\mathcal P}} \boxtimes {{\mathcal P}} )$ stands for composing ${\mathcal P}$ with ${\mathcal O}_{\Delta^\mathrm{sm}_{M/B}}$ via the first (resp.~second) factor of \mbox{$M \times_B M \times_B M$}. We refer to ${\mathcal K}$ as the \emph{convolution kernel}.
    \item[(b)] (Support) Both morphisms $\pi, \pi^\vee$ have full support, \emph{i.e.}, every simple perverse sheaf that appears in the pushforward complex $\pi_*{\mathbb{Q}}_M$ or $\pi^\vee_*{\mathbb{Q}}_{M^\vee}$ has support $B$.
\end{enumerate}

The conditions (FV1) and (FV2) refer to the following statements: for all $i + j < 2g$, we have
\begin{gather*}
\tag{FV1} {\mathfrak{F}}^{-1}_j\circ {\mathfrak{F}}_i = 0 \in \mathrm{CH}_{3g - i - j + \dim B}(M^\vee \times_B M^\vee), \\
\tag{FV2} {\mathfrak{F}}_j \circ {\mathfrak{F}}^{-1}_i = 0 \in \mathrm{CH}_{3g - i - j + \dim B}(M \times_B M).
\end{gather*}

\label{FV_reduced}
For all $i + j < 2g$, we have
\begin{gather*}
\tag{FV1} {\mathfrak{F}}^{-1}_j\circ {\mathfrak{F}}_i = 0 \in \mathrm{CH}_{3g - i - j + \dim B}(\overline{J}_C^{\phi'} \times_B \overline{J}_C^{\phi'}), \\
\tag{FV2} {\mathfrak{F}}_j \circ {\mathfrak{F}}^{-1}_i = 0 \in \mathrm{CH}_{3g - i - j + \dim B}(\overline{J}_C^{\phi} \times_B \overline{J}_C^{\phi}).
\end{gather*}

We consider the universal curve
\begin{equation}\label{univ_curve1}
C_{g,n} \to \overline{{\mathcal M}}_{g,n}
\end{equation}
over the moduli of stable marked curves (or rather, the base change to the moduli of stable marked curves with a level structure constructed in \cite{ACV}). Since we assume $n\geq 1$, there is a section through the smooth locus of the family. Using this section, universal fine compactified Jacobians of different degrees are identified. So we only need to prove that 
\[
{\mathbb{H}}^{0,\phi}_{g,n} \simeq {\mathbb{H}}^{0,\phi'}_{g,n}
\]
with $\phi, \phi'$ nondegenerate. In view of Theorem \ref{thm_main_reduced}, it suffices to check that 
\begin{enumerate}
    \item[(i)] the universal curve (\ref{univ_curve1}) is $\delta$-regular,
    \item[(ii)] the universal fine compactified Jacobian $\overline{J}^{0,\phi}_{g,n}$ is nonsingular, and
    \item[(iii)] the morphism $\pi: \overline{J}^{0,\phi}_{g,n} \to \overline{{\mathcal M}}_{g,n}$ has full support,
\end{enumerate}  
where we assume in (ii, iii) that $\phi$ is nondegenerate. 

Indeed,  (ii) is given by \cite[Corollary 4.4]{KP}; (i) and (iii) are given by \cite[Fact 2.4 and Theorem~1.9]{MSV}. This completes the proof.

\label{cor:b}
    If $g\ge 2$, we have
    \begin{multline*}
        t \cdot \pi_{1*}\left(\frac{\Theta^{g-1}}{(g-1)!}\cup \frac{\kappa_{0,1}^3}{3!}\right)
    = t^2\cdot \pi_{2*}\left( \frac{\Theta^{g-1}}{(g-1)!}\cup \frac{\kappa_{0,1}^3}{3!}\right) \\
    + 4b\cdot \left( [\mathsf{DR}^2_g(b ;a_1)]_{b^4} - \frac{1}{2} ( [\mathsf{DR}^1_g(b;a_1)]_{b^2} )^2 \right).
    \end{multline*}

By (\ref{eq:int}) and Lemma \ref{lem:a}, we obtain
    \begin{equation}\label{eq:bv}
        c \cdot \pi_{1*}(\Theta^{g-1} \cup \kappa_{0,1}^3) = \pi_{2*} ((a\Theta + b\kappa_{0,1} +\beta)^{g-1} \cup (t\kappa_{0,1} + \beta')^3).
    \end{equation}
    Expanding the right-hand side, only the terms
    \begin{equation}\label{terms2}
        \pi_{2*}(\Theta^{g-1}\cup \kappa_{0,1}^3), \quad \pi_{2*}(\Theta^{g-1}\cup \kappa_{0,1}^2\cup \beta'), \quad \pi_{2*}(\Theta^{g-2}\cup \kappa_{0,1}^4)
    \end{equation}
    contribute by (\ref{ThetaKappa}) and Lemma \ref{lem:lowp}. 

    The second term of (\ref{terms2}) simplifies to
    \begin{align*}
        \pi_{2*}\big(\Theta^{g-1} \cup \kappa_{0,1}^2 \cup \beta') & = \pi_{2*}(\Theta^{g-1}\cup \kappa_{0,1}^2) \cup \beta'\\
        & = -2!(g-1)! [\mathsf{DR}^1_g(b;a_1)]_{b^2} \cup \frac{2b}{t}[\mathsf{DR}^1_g(b;a_1)]_{b^2}
    \end{align*}
    where the first equality follows from the projection formula and the second follows from \eqref{eq:dr1} and Lemma~\ref{lem:beta}.
    By Theorem \ref{thm:bmp}, the third term of (\ref{terms2}) equals to 
    \[\pi_{2*}(\Theta^{g-2}\cup \kappa_{0,1}^4) = 4!(g-2)! [\mathsf{DR}^2_g(b;a_1)]_{b^4}.\]
    We conclude the desired formula by comparing the coefficients of the terms in \eqref{eq:bv} and \eqref{terms2} respectively.

The universal double ramification cycle relations provide an algorithm to calculate the classes of the form
\begin{equation}\label{pushforward1}
\pi_{*}( \Theta^{k} \cup \kappa^l_{0,1} \cup [\Gamma_{g_1}^\pm]) \in H^4(\overline{\mathcal{M}}_{g,1}, {\mathbb{Q}}), \quad k+l = g,
\end{equation}
which leads to the proof of both identities above. Since the full proof is lengthy but the idea is straightforward, we summarize the computational scheme here and leave the details to Section~\ref{sec:4.9}.

A class (\ref{pushforward1}) must be a multiple of the class $[\Gamma_{g_1}]$, and it suffices to determine the coefficient. First, we use Lemma \ref{lem:lowg} to distribute the monomial $\Theta^{k}\cup \kappa^l_{0,1}$ among the vertices of $\Gamma_{g_1}^\pm$; then we apply the relations in Section \ref{sec:4.3} at each vertex. For dimension reasons, the only terms that can contribute nontrivially to the pushforward are those corresponding to the stratum~$\Gamma_{g_1}'$, decorated by monomials of $\Theta$ divisors on stable vertices. These terms can be computed by successive applications of the universal double ramification cycle relations.

By a general result of Raynaud \cite[Corollary XIII 2.4 and Proposition XIII 2.6]{Ray}, for any regular and quasicompact base $B$ and any abelian scheme $A \to B$, the first \'etale cohomology~$H^1_{\text{\'et}}(B, A)$ is a torsion group. This implies the existence of a positive integer $N$ for which the pushforward torsor
\[
[N]_*T := T \overset{A}{\times} A
\]
via the ``multiplication by $N$'' map $[N]: A \to A$ is isomorphic to the trivial torsor $A$. Here the $A$-action on the second factor $A$ is defined through $[N]$.

The natural morphism $T \to [N]_*T$ then yields a morphism
\[
\varphi: T \to A
\]
which is fiberwise an isogeny up to translation over $B$.

We consider the morphism of relative Chow motives 
\begin{equation}\label{motives}
\varphi^*: h(A/B) \rightarrow h(T/B).
\end{equation}
Since (\ref{motives}) is induced by the pullback of a morphism, it automatically preserves the cup-product, and it is an isomorphism by the conservativity result \cite[Lemma A.6]{AHPL}.

More precisely, we observe that it is enough to prove the isomorphism after base change to the algebraic closure of the base field. When the base field is algebraically closed (or more generally a perfect field), the category of relative Chow motives over~$B$, in the sense of either~\cite{DM} or \cite{CH}, admits a fully faithful embedding in the category of Beilinson motives $\mathrm{DM}_{\mathord{\mathchoice
  {\mbox{\fontsize\tf@size\z@\usefont{T2A}{\rmdefault}{m}{n}\CYRB}}
  {\mbox{\fontsize\tf@size\z@\usefont{T2A}{\rmdefault}{m}{n}\CYRB}}
  {\mbox{\fontsize\sf@size\z@\usefont{T2A}{\rmdefault}{m}{n}\CYRB}}
  {\mbox{\fontsize\ssf@size\z@\usefont{T2A}{\rmdefault}{m}{n}\CYRB}}
}}(B)$ of~\cite{CD}; see \emph{e.g.}~\cite{Jin}. By the comparison theorem \cite[Theorem~16.2.18]{CD} between $\mathrm{DM}_{\mathord{\mathchoice
  {\mbox{\fontsize\tf@size\z@\usefont{T2A}{\rmdefault}{m}{n}\CYRB}}
  {\mbox{\fontsize\tf@size\z@\usefont{T2A}{\rmdefault}{m}{n}\CYRB}}
  {\mbox{\fontsize\sf@size\z@\usefont{T2A}{\rmdefault}{m}{n}\CYRB}}
  {\mbox{\fontsize\ssf@size\z@\usefont{T2A}{\rmdefault}{m}{n}\CYRB}}
}}(B)$ and the category of \'etale motives $\mathrm{DA}_{\text{\'et}}(B, {\mathbb{Q}})$ with $\mathbb{Q}$-coefficients (and without transfers), and by \cite[Lemma~A.6]{AHPL}, it suffices to verify that \eqref{motives} is an isomorphism when pulled back to any geometric point of $B$. The latter statement is immediate since $\varphi$ is fiberwise an isogeny up to translation.

Finally, the last claim follows from the construction of the multiplicative Chow--K\"unneth decomposition for abelian schemes in \cite{DM}.
